use serde::{Deserialize, Serialize};

#[derive(Debug, Deserialize, Serialize)]
pub struct ToolOutput {
    pub content: Vec<ContentBlock>,
}

#[derive(Debug, Deserialize, Serialize)]
pub enum ContentBlock {
